/* Official occupational annual means. No salary is inferred from a degree title. */
var SalaryCore=(()=>{const examples={'Electrical Engineering':'17-2071','Computer Science':'15-1252','Mechanical Engineering':'17-2141','Psychology':'13-1071','Nursing':'29-1141','Business Administration':'13-1111','Design':'27-1024','Environmental Science':'19-2041'};function lookup(data,state,soc){const value=data.annualMeanByState[state]?.[soc];return typeof value==='number'&&Number.isFinite(value)?value:null}return{examples,lookup}})();
let salaryDataPromise,salaryState='WA',salaryOccupation='';
function salaryPanel(){return `<section class="salary-panel degree-optimizer" data-salary-panel><span class="eyebrow">YOUR DIRECTION, IN THE REAL WORLD</span><h2>What could this career pay?</h2><p>Compare average annual pay in all 50 states and Washington, DC. Choose an occupation: a major can lead to many different careers.</p><div data-salary-controls role="status">Loading official salary figures…</div><div class="salary-reading" data-salary-reading aria-live="polite"></div><p class="quiet-note">Published occupational averages include workers at different experience levels. They are not starting salaries, take-home pay or a promise of what a graduate will earn.</p></section>`}
function salaryPage(){return journeyPage(2,'A direction. A place. A clearer picture.',salaryPanel(),'explore')}
async function bindSalaryPanels(){const panels=[...document.querySelectorAll('[data-salary-panel]')];if(!panels.length)return;try{if(!salaryDataPromise)salaryDataPromise=fetch('salary-data.json').then(r=>{if(!r.ok)throw Error('Salary data could not load. Please try again.');return r.json()}).catch(e=>{salaryDataPromise=null;throw e});const data=await salaryDataPromise;if(!salaryOccupation){const major=state.profile?.major||'';salaryOccupation=SalaryCore.examples[major]||(/informatics|computer|software/i.test(major)?'15-1252':'17-2071')}for(const panel of panels){if(!panel.isConnected)continue;const controls=panel.querySelector('[data-salary-controls]');controls.removeAttribute('role');controls.innerHTML=`<div class="form-grid"><label>State<select data-salary-state>${Object.entries(data.states).sort((a,b)=>a[1].localeCompare(b[1])).map(([code,name])=>`<option value="${esc(code)}" ${code===salaryState?'selected':''}>${esc(name)}</option>`).join('')}</select></label><label>Occupation<select data-salary-occupation>${Object.entries(data.occupations).sort((a,b)=>a[1].localeCompare(b[1])).map(([code,name])=>`<option value="${esc(code)}" ${code===salaryOccupation?'selected':''}>${esc(name)} · ${esc(code)}</option>`).join('')}</select></label></div><p class="quiet-note">${Object.keys(data.occupations).length} occupations · BLS ${esc(data.referencePeriod)} · Annual mean, not median.</p>`;const draw=()=>{const region=controls.querySelector('[data-salary-state]').value,soc=controls.querySelector('[data-salary-occupation]').value,value=SalaryCore.lookup(data,region,soc);salaryState=region;salaryOccupation=soc;panel.querySelector('[data-salary-reading]').innerHTML=`<span class="eyebrow">${esc(data.occupations[soc])} · ${esc(data.states[region])}</span><strong>${value===null?'Not published':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(value)}</strong><span>${value===null?'No annual mean estimate is available for this occupation and state in this source.':'average per year · USD'}</span><p>${esc(data.source)} · ${esc(data.referencePeriod)}</p>${value===null?'<p>Try another state or occupation. We do not substitute a national or neighboring-state estimate.</p>':''}<details><summary>Source and meaning</summary><p>BLS Occupational Employment and Wage Statistics, state estimates, A_MEAN field. These are workplace-location estimates. Self-employed workers are outside OEWS coverage.</p><p>Source: ${esc(data.sourceUrl)}</p></details>`};controls.querySelectorAll('select').forEach(el=>el.onchange=draw);draw()}}catch(e){for(const p of panels)if(p.isConnected)p.querySelector('[data-salary-controls]').textContent=e.message}}
function installSalaries(){for(const item of ['results','explore','career']){if(item==='results'){const prior=results;results=()=>prior()+salaryPanel()}if(item==='explore'){const prior=explore;explore=()=>prior()+salaryPanel()}if(item==='career'){const prior=career;career=()=>prior()+salaryPanel()}}const priorBind=bind;bind=()=>{priorBind();bindSalaryPanels()}}
function prioritySchoolRank(value){const s=String(value);return /(?:UW|Washington) Seattle/.test(s)?0:/(?:UW|Washington) Bothell/.test(s)?1:s==='Bellevue College'?2:3}
function installPriorityColleges(){const order=(a,b)=>prioritySchoolRank(a.name||a.institution||a.college||a)-prioritySchoolRank(b.name||b.institution||b.college||b);ProgramCatalog.institutions.sort(order);ProgramCatalog.programs.sort(order);ProductCore.institutions.sort(order);schools.sort(order);CollegeSources.resources.sort(order);DeadlineEvidence.calendars.sort(order)}
if(typeof module!=='undefined')module.exports=SalaryCore;
